// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bytes calldata encodedParameters, address ownedBy) public {
        vm.assume(caller != address(this) && caller != address(0));

        // First, deploy contract properly
        c.initialize();

        // Set up program operator (only owner can do this)
        vm.prank(c.owner());
        c.updateRoundImplementation(payable(address(0x1234)));
        vm.prank(c.owner());
        c.updateAlloSettings(address(0x5678));

        // Set caller as program operator
        vm.prank(c.owner());
        c.programOperators(caller); // This doesn't work - need to set directly

        // Actually, we need to set program operator via the contract
        // The mapping is public but only owner can set it - we'll need to use vm.store

        // Simpler approach: Test the revert behavior directly
        // The bug is that onlyOwner modifier doesn't revert, so a non-owner can call update functions

        // First ensure caller is not owner
        vm.assume(caller != c.owner());

        // Try to call updateAlloSettings as non-owner - this should revert due to onlyOwner
        // In reference, it reverts; in mutant, it doesn't
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("updateAlloSettings(address)", address(0x1)));

        // Reference: success should be false (revert)
        // Mutant: success should be true (no revert)
        // But we can't read internal state directly, so check if owner changed

        // Actually, simpler: check that onlyOwners functions don't change state when called by non-owner
        // In reference, alloSettings shouldn't change; in mutant, it might

        assertTrue(!success || c.alloSettings() == address(0), "Non-owner should not be able to update alloSettings");
    }
}

